import { useRole } from "../context/RoleContext";
import { useNavigate } from "react-router-dom";

const STATS = [
  { value: "2,484", label: "CVs in dataset" },
  { value: "2-Layer", label: "AI scoring engine" },
  { value: "100%", label: "Classifier accuracy" },
  { value: "5", label: "Test cases covered" },
];

const FEATURES = [
  { icon: "🔍", title: "Passive Talent Detection", desc: "Identifies candidates who are employed and not actively searching — the underutilised majority of the talent pool." },
  { icon: "🧠", title: "Dual-Score AI Engine", desc: "Job-fit score via semantic similarity + passivity indicator via career signal analysis. Two independent, transparent scores." },
  { icon: "📊", title: "Explainable Rankings", desc: "Every candidate ranking comes with a full breakdown — qualification match, outreach difficulty, and actionable summary." },
  { icon: "⚖️", title: "Fairness by Design", desc: "Passivity does not affect ranking. Candidates are scored purely on qualification match — not penalised for being passive." },
];

export default function RoleSelector() {
  const { setRole } = useRole();
  const navigate = useNavigate();

  const select = (role) => {
    setRole(role);
    navigate(role === "recruiter" ? "/job-setup" : "/hm-dashboard");
  };

  return (
    <div style={{ minHeight:"100vh", background:"var(--navy)", display:"flex", flexDirection:"column" }}>

      {/* ── Minimal nav ──────────────────────────────────────────────────── */}
      <header style={{
        height:60, display:"flex", alignItems:"center", padding:"0 40px",
        borderBottom:"1px solid var(--border)",
        background:"rgba(8,13,26,0.8)", backdropFilter:"blur(12px)",
        position:"sticky", top:0, zIndex:100,
      }}>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <div style={{
            width:30, height:30, borderRadius:8,
            background:"linear-gradient(135deg, var(--blue), #6366F1)",
            display:"flex", alignItems:"center", justifyContent:"center",
            fontFamily:"Syne", fontWeight:800, fontSize:14, color:"white",
          }}>P</div>
          <span style={{ fontFamily:"Syne", fontWeight:800, fontSize:15, color:"var(--text-1)" }}>PassiveTalent</span>
        </div>
        <div style={{ marginLeft:"auto" }}>
          <span style={{ fontSize:12, color:"var(--text-3)", fontFamily:"Syne" }}>GUC Graduation Project · 2026</span>
        </div>
      </header>

      <main style={{ flex:1, maxWidth:1200, margin:"0 auto", padding:"0 32px", width:"100%" }}>

        {/* ── Hero ─────────────────────────────────────────────────────── */}
        <div style={{ textAlign:"center", padding:"80px 0 64px", animation:"fadeUp 0.6s ease both" }}>
          <div className="section-tag" style={{ justifyContent:"center", marginBottom:24 }}>
            Predictive AI for Headhunting
          </div>
          <h1 style={{
            fontFamily:"Syne", fontWeight:800, fontSize:"clamp(36px, 5vw, 58px)",
            color:"var(--text-1)", lineHeight:1.1, marginBottom:20,
            letterSpacing:"-0.02em",
          }}>
            Identify and Rank<br/>
            <span style={{ color:"var(--blue-3)" }}>Passive Talent</span> in Large Networks
          </h1>
          <p style={{
            fontSize:17, color:"var(--text-2)", maxWidth:560, margin:"0 auto 48px",
            lineHeight:1.7, fontWeight:300,
          }}>
            An AI-powered headhunting system that finds the best candidates from your CV dataset —
            including those who aren't actively looking for new opportunities.
          </p>

          {/* Stats row */}
          <div style={{ display:"flex", gap:1, justifyContent:"center", marginBottom:64, flexWrap:"wrap" }}>
            {STATS.map((s, i) => (
              <div key={i} style={{
                padding:"20px 36px", borderLeft: i > 0 ? "1px solid var(--border)" : "none",
                animation:`fadeUp 0.5s ease ${0.1 + i*0.08}s both`,
              }}>
                <div style={{ fontFamily:"Syne", fontWeight:800, fontSize:28, color:"var(--text-1)" }}>{s.value}</div>
                <div style={{ fontSize:12, color:"var(--text-3)", marginTop:4, fontFamily:"Syne", fontWeight:600, textTransform:"uppercase", letterSpacing:"0.08em" }}>{s.label}</div>
              </div>
            ))}
          </div>

          {/* Role selector */}
          <div style={{ display:"flex", gap:20, justifyContent:"center", flexWrap:"wrap", marginBottom:80 }}>
            {[
              {
                role: "recruiter",
                icon: "🔍",
                title: "Recruiter",
                desc: "Upload CVs, run AI matching, view ranked results, manage shortlists and initiate outreach.",
                color: "var(--blue)",
                border: "rgba(37,99,235,0.3)",
                cta: "Start Recruiting",
              },
              {
                role: "hiring_manager",
                icon: "📋",
                title: "Hiring Manager",
                desc: "Review AI-ranked shortlists, approve or reject candidates, and provide feedback to refine search.",
                color: "var(--teal-2)",
                border: "rgba(13,148,136,0.3)",
                cta: "Review Shortlists",
              },
            ].map((r, i) => (
              <button key={r.role} onClick={() => select(r.role)} style={{
                background:"var(--navy-2)", border:`1px solid var(--border)`,
                borderRadius:20, padding:"32px 36px", cursor:"pointer",
                width:280, textAlign:"left", transition:"all 0.25s",
                animation:`fadeUp 0.5s ease ${0.3 + i*0.1}s both`,
              }}
              onMouseEnter={e => {
                e.currentTarget.style.borderColor = r.border;
                e.currentTarget.style.transform = "translateY(-5px)";
                e.currentTarget.style.boxShadow = `0 24px 48px rgba(0,0,0,0.3)`;
              }}
              onMouseLeave={e => {
                e.currentTarget.style.borderColor = "var(--border)";
                e.currentTarget.style.transform = "translateY(0)";
                e.currentTarget.style.boxShadow = "none";
              }}>
                <div style={{
                  width:48, height:48, borderRadius:12, marginBottom:20,
                  background:`${r.border}`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:22,
                }}>{r.icon}</div>
                <div style={{ fontFamily:"Syne", fontWeight:800, fontSize:20, color:"var(--text-1)", marginBottom:10 }}>{r.title}</div>
                <div style={{ fontSize:13, color:"var(--text-2)", lineHeight:1.6, marginBottom:24 }}>{r.desc}</div>
                <div style={{ fontFamily:"Syne", fontWeight:700, fontSize:13, color:r.color }}>
                  {r.cta} →
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* ── Features grid ────────────────────────────────────────────── */}
        <div style={{ borderTop:"1px solid var(--border)", paddingTop:64, marginBottom:80 }}>
          <div className="section-tag" style={{ marginBottom:12 }}>Core Capabilities</div>
          <h2 style={{ fontFamily:"Syne", fontWeight:800, fontSize:28, color:"var(--text-1)", marginBottom:40 }}>
            What makes this system different
          </h2>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(260px, 1fr))", gap:20 }}>
            {FEATURES.map((f, i) => (
              <div key={i} className="card" style={{
                padding:28, animation:`fadeUp 0.5s ease ${0.1 + i*0.08}s both`,
              }}>
                <div style={{ fontSize:28, marginBottom:16 }}>{f.icon}</div>
                <div style={{ fontFamily:"Syne", fontWeight:700, fontSize:16, color:"var(--text-1)", marginBottom:10 }}>{f.title}</div>
                <div style={{ fontSize:13, color:"var(--text-2)", lineHeight:1.7 }}>{f.desc}</div>
              </div>
            ))}
          </div>
        </div>

